SIGNAL SAL: STD_LOGIC_VECTOR(639 DOWNTO 0);
SIGNAL PIX: STD_LOGIC;
SIGNAL COLOR: INTEGER RANGE 0 TO 2;
BEGIN

	PROCESS(CLK, RST2, HPOS, VPOS, VIDEO) -- PROCESO PARA COLOREAR LOS PIXELES
	BEGIN
		IF RST2 = '1' THEN
			COLOR <= 2;
		ELSIF FALLING_EDGE(CLK) THEN
			IF VIDEO = '1' THEN
				IF (HPOS >= 0 AND HPOS <= 639) AND (VPOS >= 0 AND VPOS <= 479) THEN
					SAL <= ROM(VPOS);
					PIX <= SAL(HPOS);
					IF PIX = '0' THEN
						COLOR <= 0; 
					ELSE
						COLOR <= 1;
					END IF;
				ELSE
						COLOR <= 2;
				END IF;
			END IF;
		END IF;
		
		IF COLOR = 0 THEN
			R <= "0000"; 
			G <= "0000"; 
			B <= "0000";
		ELSIF COLOR = 1 THEN
			R <= "0000"; 
			G <= "1111"; 
			B <= "0000";
		ELSIF CoLOR = 2 THEN 
			R <= "0000"; 
			G <= "1111"; 
			B <= "0000";
		ELSE
			R <= "0000"; 
			G <= "1111"; 
			B <= "1111";
	END IF;
	END PROCESS;
	

END BEAS;
